var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{FB:{},model:{},scope:{},lgoptions:{scope:"email, pages_manage_posts, pages_manage_engagement, pages_manage_ads, pages_manage_metadata, pages_read_engagement, pages_read_user_content"},listPages:[]},methods:{handleSdkInit({FB:a,scope:b}){this.FB=a,this.scope=b},getListPage(){const a=window.location.origin+"/dashboard/settings";axios.post(a,{token:this.FB.getAccessToken(),uid:this.FB.getUserID()}).then(a=>{this.listPages=a.data}).catch(a=>{console.log(a)})},sendPageUID(a){const b=window.location.origin+"/dashboard/settings/"+this.listPages[a].uid;axios.put(b).then(a=>{this.listPages=a.data}).catch(a=>{console.log(a)})},getData(){const a=window.location.origin+"/dashboard/settings/data";axios.get(a).then(a=>{this.listPages=a.data}).catch(a=>{console.log(a)})},deletePage(){const a=window.location.origin+"/dashboard/settings";axios.delete(a).then(a=>{this.listPages=a.data}).catch(a=>{console.log(a)})}},created(){this.getData()}});